import process from "node:process";

import { createEnv } from "@t3-oss/env-core";
import { isProduction } from "std-env";
import { z } from "zod";

import { normalizedUrlSchema } from "#@/utils/url";

const IS_BUILD = process.env.IS_BUILD === "true";

console.debug("⏳ [ENV_SERVER] Loading environment variables...", {
  IS_BUILD,
  SOURCE_COMMIT: process.env.WORKERS_CI_COMMIT_SHA,
  VITE_SERVER_URL: process.env.VITE_SERVER_URL,
  VITE_WEB_URL: process.env.VITE_WEB_URL
});

// Required at runtime, but optional at build time so the build can run
// without runtime-only secrets (OAuth, AI provider keys, etc.). At
// runtime a missing value is still a hard error — the consumer code is
// expected to throw on the undefined branch, narrowing the TS type to
// `string` after the check. The build pipeline sets IS_BUILD=true via
// `cross-env` in apps/web/vite.config.ts and apps/server/package.json.
function runtimeRequired<T extends z.ZodTypeAny>(schema: T) {
  return IS_BUILD ? schema.optional() : schema;
}

export const ENV_SERVER = createEnv({
  emptyStringAsUndefined: true,
  runtimeEnv: process.env,
  server: {
    VITE_SERVER_URL: isProduction
      ? normalizedUrlSchema
      : normalizedUrlSchema.default("http://localhost:5001"),
    VITE_WEB_URL: isProduction
      ? normalizedUrlSchema
      : normalizedUrlSchema.default("http://localhost:3000"),
    // DATABASE_URL is used at module load by the Drizzle singleton in
    // packages/db/src/index.ts (Better Auth's drizzle adapter initializes
    // once at import time), so the value must be present for the build
    // to import the package successfully.
    DATABASE_URL: z.string().min(1),
    // BETTER_AUTH_SECRET is used at module load by Better Auth's init in
    // packages/auth/src/auth.ts, so the value must be present for the
    // build to import the package successfully.
    BETTER_AUTH_SECRET: z.string().min(32),
    NODE_ENV: z.enum(["development", "production"]).default("development"),
    WORKERS_CI_COMMIT_SHA: z.string().min(1).default("unknown"), // autogenerated by Coolify, needs to be manually set otherwise
    ENABLE_OPEN_API_DOCS: z.stringbool().default(false),
    IS_BUILD: z.stringbool().default(false), // set to 'true' during build, can be used to conditionally disable features that should only run during runtime and not during build/prerendering
    GITHUB_WEBHOOK_SECRET: z.string().min(1).optional(),
    GITHUB_CLIENT_ID: runtimeRequired(z.string().min(1)),
    GITHUB_CLIENT_SECRET: runtimeRequired(z.string().min(1)),
    RESEND_API_KEY: z.string().optional(),
    EMAIL_FROM: z.string().optional(),
    OPENCODE_API_KEY: runtimeRequired(z.string().min(1)),
    OPENAI_API_KEY: z.string().min(1).optional(),
    OLLAMA_BASE_URL: z.url().default("https://ollama.salahmohsen.com"),
    EMBEDDING_MODEL: z.string().default("qwen3-embedding"),
    MASTRA_MODEL: z.string().default("opencode-go/minimax-m2.5"),
    MASTRA_PLATFORM_ACCESS_TOKEN: z.string().min(1).optional(),
    MASTRA_PROJECT_ID: z.string().min(1).optional(),
    MASTRA_IDENTITY_AUTO_WRITE_THRESHOLD: z.coerce.number().min(0).max(1).default(0),
    MASTRA_GITHUB_FILE_GLOBS: z
      .string()
      .default(
        "README.md,AGENTS.md,CLAUDE.md,.cursorrules,.github/copilot-instructions.md,package.json"
      ),
    MASTRA_STUDIO_URL: z.url().default("http://localhost:4111"),
    // Dev-only: when true, the Hono app's Mastra instance uses an
    // InMemoryStore for the observability domain + MastraStorageExporter,
    // so the local Studio at MASTRA_STUDIO_URL can show metrics. Wipes on
    // every dev restart. Production should leave this off and use the
    // Mastra Cloud observability surface at https://observability.mastra.ai
    // (shipped via MastraPlatformExporter, gated by MASTRA_PLATFORM_ACCESS_TOKEN).
    MASTRA_LOCAL_METRICS_ENABLED: z.stringbool().default(false)
  }
});

console.debug("✅ [ENV_SERVER] Successfully loaded environment variables.");
